122	type usageErrorf string
123	
124	func (e usageErrorf) Error() string { return string(e) }
125	
126	func usageError(format string, a ...any) error {
127		return usageErrorf(fmt.Sprintf(format, a...))
128	}
129	
130	func cmdCustomerAdd(dir, id, name, priceText string) error {
131		if strings.TrimSpace(id) == "" {
132			return fmt.Errorf("客户标识不能为空")
133		}
134		if strings.TrimSpace(name) == "" {
135			return fmt.Errorf("客户名称不能为空")
136		}
137		price, err := parsePrice(priceText)
138		if err != nil {
139			return err
140		}
141	
142		s, err := loadStore(dir)
143		if err != nil {
144			return err
145		}
146		if _, exists := s.Customers[id]; exists {
147			return fmt.Errorf("客户标识 %q 已存在，客户单价创建后不可修改", id)
148		}
149		s.Customers[id] = &customer{ID: id, Name: name, Price: price}
150		if err := s.save(); err != nil {
151			return err
152		}
153		fmt.Fprintf(stdout, "已登记客户 %q（%s），固定单价 %d 分（%s）\n", id, name, price, moneyFen(price))
154		return nil
155	}
156	
157	func parsePrice(text string) (int64, error) {
158		text = strings.TrimSpace(text)
159		price, err := strconv.ParseInt(text, 10, 64)
160		if err != nil {
161			return 0, fmt.Errorf("单价 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
162		}
163		if price < 0 {
164			return 0, fmt.Errorf("单价必须是非负整数分，收到 %d", price)
165		}
166		return price, nil
167	}
168	
169	// parsedRow 是导入文件中一行解析后的候选用量。
170	type parsedRow struct {
171		line int // 文件中的行号（含表头），用于报错定位
172		rec  usageRecord
173		t    time.Time
174	}
175	
176	func cmdUsageImport(dir, file string) error {
177		var reader io.ReadCloser
178		var source string
179		if file == "-" {
180			reader = io.NopCloser(os.Stdin)
181			source = "标准输入"
182		} else {
183			f, err := os.Open(file)
184			if err != nil {
185				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
186			}
187			reader = f
188			source = file
189		}
190		defer reader.Close()
191	
192		rows, parseErrs := parseUsageFile(reader)
193	
194		s, err := loadStore(dir)
195		if err != nil {
196			return err
197		}
198	
199		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
200		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
201		var problems []string
202		problems = append(problems, parseErrs...)
203	
204		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
205		var ordered []*parsedRow
206		newCount, dupCount := 0, 0
207	
208		for _, r := range rows {
209			cust, ok := s.Customers[r.rec.CustomerID]
210			if !ok {
211				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
212				continue
213			}
214			// 金额可行性预检：数量×固定单价不得溢出（金额单位：分）。
215			if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
216				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
217				continue
218			}
219	
220			// 去重判定同时对“库中已有”和“本文件内已出现”生效。
221			var existing *usageRecord
222			if inStore, ok := s.Usage[r.rec.ID]; ok {
223				existing = inStore
224			} else if inBatch, ok := accepted[r.rec.ID]; ok {
225				existing = &inBatch.rec
226			}
227	
228			if existing != nil {
229				if !sameUsage(existing, &r.rec, r.t) {
230					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
231						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
232					continue
233				}
234				dupCount++
235				continue
236			}
237	
238			// 全新标识：不得进入该客户已封账的 UTC 自然月。
239			month := r.t.UTC().Format("2006-01")
240			if s.sealed(r.rec.CustomerID, month) {
241				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
242					r.line, r.rec.CustomerID, month, r.rec.ID))
243				continue
244			}
245	
246			rr := r
247			accepted[r.rec.ID] = rr
248			ordered = append(ordered, rr)
249			newCount++
250		}
251	
252		if len(problems) > 0 {
253			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
254		}
255	
256		for _, r := range ordered {
257			rec := r.rec
258			s.Usage[rec.ID] = &rec
259		}
260		if err := s.save(); err != nil {
261			return err
262		}
263		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
264		return nil
265	}
266	
267	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
268	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
269		cr := csv.NewReader(r)
270		cr.FieldsPerRecord = 4
271		cr.TrimLeadingSpace = true
272	
273		header, err := cr.Read()
274		if err == io.EOF {
275			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
276		}
277		if err != nil {
278			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
279		}
280		for i := range header {
281			header[i] = strings.TrimSpace(header[i])
282		}
283		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
284			header[2] != "time" || header[3] != "quantity" {
285			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
286		}
287	
288		var rows []*parsedRow
289		var problems []string
290		line := 1
291		for {
292			rec, err := cr.Read()
293			if err == io.EOF {
294				break
295			}
296			line++
297			if err != nil {
298				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
299				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
300					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
301					break
302				}
303				continue
304			}
305			for i := range rec {
306				rec[i] = strings.TrimSpace(rec[i])
307			}
308	
309			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
310			if id == "" {
311				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
312				continue
313			}
314			if custID == "" {
315				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
316				continue
317			}
318			t, err := time.Parse(time.RFC3339, ts)
319			if err != nil {
320				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
321				continue
322			}
323			qty, err := strconv.ParseInt(qtyText, 10, 64)
324			if err != nil {
325				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
326				continue
327			}
328			if qty <= 0 {
329				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
330				continue
331			}
332	
333			rows = append(rows, &parsedRow{
334				line: line,
335				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
336				t:    t,
337			})
338		}
339		return rows, problems
340	}
341	
342	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
343	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
344	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
345		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
346			return false
347		}
348		et, err := time.Parse(time.RFC3339, existing.Time)
349		if err != nil {
350			return existing.Time == candidate.Time
351		}
352		return et.Equal(candidateT)
353	}
354	
355	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
356	func validMonth(m string) bool {
357		t, err := time.Parse("2006-01", m)
358		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
359			return false
360		}
361		return true
362	}
363	
364	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
365	func inMonth(rfc3339, month string) bool {
366		t, err := time.Parse(time.RFC3339, rfc3339)
367		if err != nil {
368			return false
369		}
370		return t.UTC().Format("2006-01") == month
371	}
372	
373	func cmdBillSettle(dir, customerID, month string) error {
374		if !validMonth(month) {
375			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
376		}
377		s, err := loadStore(dir)
378		if err != nil {
379			return err
380		}
381		cust, ok := s.Customers[customerID]
382		if !ok {
383			return fmt.Errorf("客户标识 %q 不存在", customerID)
384		}
385	
386		key := billKey(customerID, month)
387		if existing, ok := s.Bills[key]; ok {
388			// 幂等：同一客户同一月份重复结算，直接返回原账单，
389			// 不重新计费、不产生新账单或调整、不落盘。
390			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
391			printBill(existing, cust, s)
392			return nil
393		}
394	
395		// 归集该客户 UTC 自然月内的全部用量，区间为左闭右开 [月初, 下月初)。
396		var inMonthRecs []*usageRecord
397		for _, u := range s.Usage {
398			if u.CustomerID == customerID && inMonth(u.Time, month) {
399				inMonthRecs = append(inMonthRecs, u)
400			}
401		}
402		if len(inMonthRecs) == 0 {
403			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
404		}
405		sortByInstant(inMonthRecs)
406	
407		lines := make([]billLine, 0, len(inMonthRecs))
408		var totalQty, totalFee int64
409		for _, u := range inMonthRecs {
410			lineFee, err := mul64(u.Quantity, cust.Price)
411			if err != nil {
412				return fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出，拒绝结算且不封账", u.ID, u.Quantity, cust.Price)
413			}
414			totalQty, err = add64(totalQty, u.Quantity)
415			if err != nil {
416				return fmt.Errorf("汇总数量溢出有符号 64 位整数范围，拒绝结算且不封账")
417			}
418			totalFee, err = add64(totalFee, lineFee)
419			if err != nil {
420				return fmt.Errorf("汇总金额溢出有符号 64 位整数范围，拒绝结算且不封账")
421			}
422			lines = append(lines, billLine{
423				UsageID:  u.ID,
424				Time:     u.Time,
425				Quantity: u.Quantity,
426				LineFee:  lineFee,
427			})
428		}
429	
430		b := &bill{
431			ID:         stableBillID(customerID, month),
432			CustomerID: customerID,
433			Month:      month,
434			TotalQty:   totalQty,
435			UnitPrice:  cust.Price,
436			TotalFee:   totalFee,
437			Lines:      lines,
438			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
439		}
440		s.Bills[key] = b
441	
442		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
443		if err := s.save(); err != nil {
444			delete(s.Bills, key)
445			return err
446		}
447		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
448		printBill(b, cust, s)
449		return nil
450	}
