472	func sortByInstant(us []*usageRecord) {
473		// 入参时间均已在载入/导入时校验为 RFC3339。
474		sort.Slice(us, func(i, j int) bool {
475			ti, _ := time.Parse(time.RFC3339, us[i].Time)
476			tj, _ := time.Parse(time.RFC3339, us[j].Time)
477			ui, uj := ti.UTC(), tj.UTC()
478			if !ui.Equal(uj) {
479				return ui.Before(uj)
480			}
481			return us[i].ID < us[j].ID
482		})
483	}
