533	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
534	func historyEvents(adjs []*adjustment) []string {
535		type event struct {
536			seq  int64
537			text string
538		}
539		var events []event
540		for _, a := range adjs {
541			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
542				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
543			if a.Revoked {
544				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
545					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
546			}
547		}
548		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
549		out := make([]string, len(events))
550		for i, ev := range events {
551			out[i] = ev.text
552		}
553		return out
554	}
