570	// paymentHistoryEvents 把收款登记、分配更正与撤销展开为按操作序号排序的
571	// 可读历史条目；month 为当前展示账单所在月份。收款事件展示首次登记时在
572	// 本账单的分配，更正事件展示本账单分配的前后变化，撤销事件展示被整笔取消
573	// 的最新分配。
574	func paymentHistoryEvents(s *state, pays []*payment, month string) []string {
575		type event struct {
576			seq  int64
577			text string
578		}
579		var events []event
580		for _, p := range pays {
581			alloc := p.amountFor(month)
582			events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
583				p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID)})
584			// 以首次登记分配为起点，按序号回放该收款在本账单的分配变化。
585			running := alloc
586			for _, c := range correctionsFor(s, p.ID) {
587				after := allocAmountFor(c.Allocations, month)
588				if running == 0 && after == 0 {
589					continue // 本次更正不涉及本账单
590				}
591				events = append(events, event{c.Seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
592					c.ID, c.Reason, p.ID, running, after)})
593				running = after
594			}
595			if p.Revoked {
596				// 整笔撤销取消的是撤销时的最新分配。
597				events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
598					p.ID, p.RevokeReason, p.ID, p.Total, running)})
599			}
600		}
601		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
602		out := make([]string, len(events))
603		for i, ev := range events {
604			out[i] = ev.text
605		}
606		return out
607	}
