616	// parseAmount 解析调整金额：有符号 64 位整数、非零（正数补收、负数减免）。
617	func parseAmount(text string) (int64, error) {
618		text = strings.TrimSpace(text)
619		amount, err := strconv.ParseInt(text, 10, 64)
620		if err != nil {
621			return 0, fmt.Errorf("调整金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
622		}
623		if amount == 0 {
624			return 0, fmt.Errorf("调整金额不能为零分（正数补收、负数减免）")
625		}
626		return amount, nil
627	}
