629	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
630		if !validMonth(month) {
631			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
632		}
633		if strings.TrimSpace(adjID) == "" {
634			return fmt.Errorf("调整标识不能为空")
635		}
636		amount, err := parseAmount(amountText)
637		if err != nil {
638			return err
639		}
640		if strings.TrimSpace(reason) == "" {
641			return fmt.Errorf("调整原因不能为空")
642		}
643	
644		s, err := loadStore(dir)
645		if err != nil {
646			return err
647		}
648		if _, ok := s.Customers[customerID]; !ok {
649			return fmt.Errorf("客户标识 %q 不存在", customerID)
650		}
651		b, ok := s.Bills[billKey(customerID, month)]
652		if !ok {
653			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
654		}
655	
656		if existing, ok := s.Adjustments[adjID]; ok {
657			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
658			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
659			if existing.CustomerID == customerID && existing.Month == month &&
660				existing.Amount == amount && existing.Reason == reason {
661				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
662				printAdjustment(existing, s)
663				return nil
664			}
665			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
666				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
667		}
668	
669		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
670		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
671		// 不占用该调整标识。
672		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
673		if err != nil {
674			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
675		}
676		received, err := paymentReceived(s, customerID, month)
677		if err != nil {
678			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
679		}
680		newPayable, err := addSigned64(payable, amount)
681		if err != nil {
682			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
683		}
684		if newPayable < 0 {
685			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
686		}
687		if newPayable < received {
688			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
689				newPayable, received, payable, amount)
690		}
691	
692		a := &adjustment{
693			ID:         adjID,
694			CustomerID: customerID,
695			Month:      month,
696			Amount:     amount,
697			Reason:     reason,
698			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
699		}
700		s.NextSeq++
701		a.Seq = s.NextSeq
702		s.Adjustments[adjID] = a
703	
704		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
705		// 该调整标识不被占用。
706		if err := s.save(); err != nil {
707			delete(s.Adjustments, adjID)
708			s.NextSeq--
709			return err
710		}
711		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
712			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
713		printAdjustment(a, s)
714		return nil
715	}
