816		amount, err := strconv.ParseInt(text, 10, 64)
817		if err != nil {
818			return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
819		}
820		if amount <= 0 {
