892	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
893	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
894	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
895		if strings.TrimSpace(payID) == "" {
896			return fmt.Errorf("收款标识不能为空")
897		}
898		if strings.TrimSpace(note) == "" {
899			return fmt.Errorf("收款备注不能为空")
900		}
901		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
902		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
903	
904		s, err := loadStore(dir)
905		if err != nil {
906			return err
907		}
908		if _, ok := s.Customers[customerID]; !ok {
909			return fmt.Errorf("客户标识 %q 不存在", customerID)
910		}
911		for _, al := range allocs {
912			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
913				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
914			}
915		}
916	
917		if existing, ok := s.Payments[payID]; ok {
918			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
919			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
920			// 已撤销的重放仍返回已撤销状态，不恢复实收。
921			if samePaymentContent(existing, customerID, total, note, allocs) {
922				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
923				printPayment(existing, s)
924				return nil
925			}
926			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
927				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
928		}
929	
930		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
931		for _, al := range allocs {
932			b := s.Bills[billKey(customerID, al.Month)]
933			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
934			if err != nil {
935				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
936			}
937			received, err := paymentReceived(s, customerID, al.Month)
938			if err != nil {
939				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
940			}
941			if payable == 0 {
942				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
943			}
944			if al.Amount > payable-received {
945				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
946					al.Amount, payable-received, customerID, al.Month, payable, received)
947			}
948		}
949	
950		p := &payment{
951			ID:          payID,
952			CustomerID:  customerID,
953			Total:       total,
954			Note:        note,
955			Allocations: allocs,
956			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
957		}
958		s.NextSeq++
959		p.Seq = s.NextSeq
960		s.Payments[payID] = p
961	
962		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
963		// 一切不生效，该收款标识不被占用。
964		if err := s.save(); err != nil {
965			delete(s.Payments, payID)
966			s.NextSeq--
967			return err
968		}
969		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
970		printAllocationBalances(s, p, allocs)
971		fmt.Fprintln(stdout)
972		printPayment(p, s)
973		return nil
974	}
975	
976	// samePaymentContent 按客户、总额、备注与月份-金额对应关系判定两笔收款
977	// 内容相同；分配顺序不影响身份。判重依据首次登记内容，不受后续更正影响。
978	func samePaymentContent(p *payment, customerID string, total int64, note string, allocs []paymentAllocation) bool {
979		if p.CustomerID != customerID || p.Total != total || p.Note != note {
980			return false
981		}
982		return sameAllocations(p.Allocations, allocs)
983	}
984	
985	// sameAllocations 判定两个分配列表的月份-金额对应关系相同（顺序无关）。
986	func sameAllocations(a, b []paymentAllocation) bool {
987		if len(a) != len(b) {
988			return false
989		}
990		for _, al := range b {
991			if allocAmountFor(a, al.Month) != al.Amount {
992				return false
993			}
994		}
995		return true
996	}
