1007	// printAllocationBalances 输出给定分配列表每个分配月份当前的实收与未收余额。
1008	func printAllocationBalances(s *state, p *payment, allocs []paymentAllocation) {
1009		for _, al := range allocs {
1010			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1011			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
1012			received, _ := paymentReceived(s, p.CustomerID, al.Month)
1013			fmt.Fprintf(stdout, "  月份 %s：分配 %d 分，实收 %d 分（%s），未收余额 %d 分（%s）\n",
1014				al.Month, al.Amount, received, moneyFen(received), payable-received, moneyFen(payable-received))
1015		}
1016	}
