1098	// --- 收款分配更正 ---
1099	
1100	func cmdBillCorrect(dir, payID, corrID, reason string, allocArgs []string) error {
1101		if strings.TrimSpace(payID) == "" {
1102			return fmt.Errorf("收款标识不能为空")
1103		}
1104		if strings.TrimSpace(corrID) == "" {
1105			return fmt.Errorf("更正标识不能为空")
1106		}
1107		if strings.TrimSpace(reason) == "" {
1108			return fmt.Errorf("更正原因不能为空")
1109		}
1110		allocs, err := parseAllocations(allocArgs)
1111		if err != nil {
1112			return err
1113		}
1114		// 分配顺序不影响更正身份：统一按月份升序保存与比较。
1115		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1116	
1117		s, err := loadStore(dir)
1118		if err != nil {
1119			return err
1120		}
1121		p, ok := s.Payments[payID]
1122		if !ok {
1123			return fmt.Errorf("收款标识 %q 不存在，无法更正分配", payID)
1124		}
1125	
1126		if existing, ok := s.Corrections[corrID]; ok {
1127			// 相同标识按目标收款、原因与新月份-金额对应关系判重（列表顺序无关）：
1128			// 内容相同返回原更正记录，不改分配、不增历史；后续更正或收款撤销
1129			// 不影响此规则。任何一项不同（含跨收款复用）均拒绝。
1130			if existing.PaymentID == payID && existing.Reason == reason && sameAllocations(existing.Allocations, allocs) {
1131				fmt.Fprintf(stdout, "更正 %q 已存在且内容相同，返回原更正记录（不改分配、不增历史）：\n\n", corrID)
1132				printCorrection(existing, s)
1133				return nil
1134			}
1135			return fmt.Errorf("更正标识 %q 已存在但内容不同（已有：收款=%s 原因=%q 新分配=%s），拒绝复用",
1136				corrID, existing.PaymentID, existing.Reason, formatAllocations(existing.Allocations))
1137		}
1138	
1139		// 新增更正只允许未撤销收款。
1140		if p.Revoked {
1141			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），不能新增分配更正", payID, p.RevokeReason)
1142		}
1143	
1144		// 新分配合计必须等于原收款总额（不重复收钱也不多收），全程整数运算。
1145		var sum int64
1146		for _, al := range allocs {
1147			sum, err = add64(sum, al.Amount)
1148			if err != nil {
1149				return fmt.Errorf("新分配金额合计溢出有符号 64 位整数范围，拒绝更正")
1150			}
1151		}
1152		if sum != p.Total {
1153			return fmt.Errorf("新分配合计 %d 分与原收款 %q 的总额 %d 分不一致，拒绝更正", sum, payID, p.Total)
1154		}
1155		// 新分配月份须是原客户的已结算账单。
1156		for _, al := range allocs {
1157			if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
1158				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），更正只能分配到已存在账单", p.CustomerID, al.Month)
1159			}
1160		}
1161	
1162		// 以当前最新分配为起点：撤去该笔当前分配再计入新分配后，涉及月份
1163		// 均须满足 0 ≤ 实收 ≤ 应付；其他收款不变，全部合法才整笔生效。
1164		current := currentAllocations(s, p)
1165		for _, m := range unionMonths(current, allocs) {
1166			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1167			_, payable, err := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1168			if err != nil {
1169				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝更正: %w", p.CustomerID, m, err)
1170			}
1171			received, err := paymentReceived(s, p.CustomerID, m)
1172			if err != nil {
1173				return fmt.Errorf("客户 %s 的 %s 实收累计异常，拒绝更正: %w", p.CustomerID, m, err)
1174			}
1175			// 该笔收款未撤销，其实收必然包含当前分配，撤去不会变负。
1176			received -= allocAmountFor(current, m)
1177			received, err = add64(received, allocAmountFor(allocs, m))
1178			if err != nil {
1179				return fmt.Errorf("客户 %s 的 %s 更正后实收溢出有符号 64 位整数范围，拒绝更正", p.CustomerID, m)
1180			}
1181			if received > payable {
1182				return fmt.Errorf("更正后客户 %s 的 %s 实收 %d 分将超过当前应付 %d 分，拒绝更正；全部状态保持不变",
1183					p.CustomerID, m, received, payable)
1184			}
1185		}
1186	
1187		c := &correction{
1188			ID:          corrID,
1189			PaymentID:   payID,
1190			Reason:      reason,
1191			Allocations: allocs,
1192			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1193		}
1194		s.NextSeq++
1195		c.Seq = s.NextSeq
1196		s.Corrections[corrID] = c
1197	
1198		// 更正记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1199		// 一切不生效，该更正标识不被占用。
1200		if err := s.save(); err != nil {
1201			delete(s.Corrections, corrID)
1202			s.NextSeq--
1203			return err
1204		}
1205		fmt.Fprintf(stdout, "已登记收款分配更正 %q（关联收款 %q）：\n\n", corrID, payID)
1206		printCorrection(c, s)
1207		return nil
1208	}
1209	
1210	// unionMonths 返回两个分配列表涉及月份的并集，按月份升序。
1211	func unionMonths(a, b []paymentAllocation) []string {
1212		set := make(map[string]bool, len(a)+len(b))
1213		for _, al := range a {
1214			set[al.Month] = true
1215		}
1216		for _, al := range b {
1217			set[al.Month] = true
1218		}
1219		months := make([]string, 0, len(set))
1220		for m := range set {
1221			months = append(months, m)
1222		}
1223		sort.Strings(months)
1224		return months
1225	}
1226	
1227	// allocationBefore 返回一次更正发生前该收款生效的分配：上一条更正的
1228	// 新分配，或（首次更正时）收款的原始分配。
1229	func allocationBefore(s *state, c *correction) []paymentAllocation {
1230		before := s.Payments[c.PaymentID].Allocations // 载入时已校验存在
1231		var latest *correction
1232		for _, o := range s.Corrections {
1233			if o.PaymentID == c.PaymentID && o.Seq < c.Seq && (latest == nil || o.Seq > latest.Seq) {
1234				latest = o
1235			}
1236		}
1237		if latest != nil {
1238			before = latest.Allocations
1239		}
1240		return before
1241	}
1242	
1243	// printCorrection 输出单笔更正记录：关联收款、标识、原因、完整前后分配，
1244	// 以及前后分配涉及月份的当前余额。
1245	func printCorrection(c *correction, s *state) {
1246		p := s.Payments[c.PaymentID] // 载入时已校验存在
1247		before := allocationBefore(s, c)
1248		fmt.Fprintf(stdout, "更正标识：%s\n", c.ID)
1249		fmt.Fprintf(stdout, "关联收款：%s（客户 %s，总额 %d 分（%s），备注：%s）\n",
1250			p.ID, p.CustomerID, p.Total, moneyFen(p.Total), p.Note)
1251		fmt.Fprintf(stdout, "原因：%s\n", c.Reason)
1252		fmt.Fprintf(stdout, "更正前分配：%s\n", formatAllocations(before))
1253		fmt.Fprintf(stdout, "更正后分配：%s\n", formatAllocations(c.Allocations))
1254		fmt.Fprintln(stdout, "涉及月份当前余额：")
1255		for _, m := range unionMonths(before, c.Allocations) {
1256			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1257			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1258			received, _ := paymentReceived(s, p.CustomerID, m)
1259			fmt.Fprintf(stdout, "  月份 %s：本笔分配 %d 分 → %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1260				m, allocAmountFor(before, m), allocAmountFor(c.Allocations, m),
1261				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1262		}
1263	}
1264	
1265	// --- 账后对账流水 ---
1266	
1267	// ledgerEvent 是某张已结算账单账后流水中的一个事件：调整、撤销调整、收款、
1268	// 分配更正或撤销收款。事件按全局操作序号升序回放；撤销在其发生序号抵消
1269	// 对应原操作，已撤销记录在撤销之前仍计入，不按当前撤销状态删除原事件；
1270	// 更正在其发生序号把关联收款在本账单的分配由前值替换为后值。
1271	type ledgerEvent struct {
1272		seq           int64  // 全局操作序号（调整/收款/更正及其撤销共用）
1273		kind          string // 事件类型：调整 / 撤销调整 / 收款 / 更正 / 撤销收款
1274		refID         string // 原记录标识（调整标识、收款标识或更正标识）
1275		deltaPayable  int64  // 对当前应付的影响（分，带符号）
1276		deltaReceived int64  // 对实收的影响（分，带符号）
1277		note          string // 原因（调整/更正类）或备注（收款类）
1278		linkSeq       int64  // 撤销事件关联的原操作序号；非撤销事件为 0
1279		payTotal      int64  // 收款类事件：汇款总额
1280		payAlloc      int64  // 收款类事件：本账单分配（撤销收款事件为被取消的最新分配）
1281		payID         string // 更正事件：关联收款标识
1282		beforeAlloc   int64  // 更正事件：本账单更正前分配
1283		afterAlloc    int64  // 更正事件：本账单更正后分配
1284		afterPayable  int64  // 事件后的应付（回放时填充）
1285		afterReceived int64  // 事件后的实收（回放时填充）
1286	}
1287	
1288	// billLedger 把目标账单的调整、调整撤销、收款、分配更正与收款撤销合并为
1289	// 一条按操作序号升序的流水，并以原总金额为初始应付、零实收为起点逐步回放，
1290	// 填充每个事件之后的三项余额。回放覆盖完整流水（不受查询截止序号限制）：
1291	// 序号重复、撤销先于原操作，或任一事件之后不满足 0 ≤ 实收 ≤ 应付 ≤ 有符号
1292	// 64 位最大值，都视为数据异常并拒绝——只检查最终余额会放过中间越界的存档。
1293	// 只读：不修改库、不占用序号、不新增记录。
1294	func billLedger(s *state, b *bill) ([]ledgerEvent, error) {
1295		var events []ledgerEvent
1296		for _, a := range s.Adjustments {
1297			if a.CustomerID != b.CustomerID || a.Month != b.Month {
1298				continue
1299			}
1300			events = append(events, ledgerEvent{
1301				seq: a.Seq, kind: "调整", refID: a.ID,
1302				deltaPayable: a.Amount, note: a.Reason,
1303			})
1304			if a.Revoked {
1305				neg, err := neg64(a.Amount)
1306				if err != nil {
1307					return nil, fmt.Errorf("调整 %q 的金额 %d 分无法抵消（越界），数据异常，拒绝输出流水", a.ID, a.Amount)
1308				}
1309				events = append(events, ledgerEvent{
1310					seq: a.RevokeSeq, kind: "撤销调整", refID: a.ID,
1311					deltaPayable: neg, note: a.RevokeReason, linkSeq: a.Seq,
1312				})
1313			}
1314		}
1315		for _, p := range s.Payments {
1316			if p.CustomerID != b.CustomerID {
1317				continue
1318			}
1319			// 多月汇款只以本账单分配改变实收；更正在其发生序号把本账单分配
1320			// 由前值替换为后值；整笔撤销在同一序号取消撤销时的最新分配。
1321			// 首次登记或任一次更正涉及本账单的，该收款的后续事件都纳入流水。
1322			alloc := p.amountFor(b.Month)
1323			corrs := correctionsFor(s, p.ID)
1324			involved := alloc > 0
1325			if !involved {
1326				for _, c := range corrs {
1327					if allocAmountFor(c.Allocations, b.Month) > 0 {
1328						involved = true
1329						break
1330					}
1331				}
1332			}
1333			if !involved {
1334				continue
1335			}
1336			if alloc > 0 {
1337				events = append(events, ledgerEvent{
1338					seq: p.Seq, kind: "收款", refID: p.ID,
1339					deltaReceived: alloc, note: p.Note,
1340					payTotal: p.Total, payAlloc: alloc,
1341				})
1342			}
1343			running := alloc
1344			for _, c := range corrs {
1345				after := allocAmountFor(c.Allocations, b.Month)
1346				if running == 0 && after == 0 {
1347					continue // 本次更正不涉及本账单
1348				}
1349				events = append(events, ledgerEvent{
1350					seq: c.Seq, kind: "更正", refID: c.ID,
1351					deltaReceived: after - running, note: c.Reason,
1352					payID: p.ID, beforeAlloc: running, afterAlloc: after,
1353				})
1354				running = after
1355			}
1356			if p.Revoked {
1357				events = append(events, ledgerEvent{
1358					seq: p.RevokeSeq, kind: "撤销收款", refID: p.ID,
1359					deltaReceived: -running, note: p.RevokeReason, linkSeq: p.Seq,
1360					payTotal: p.Total, payAlloc: running,
1361				})
1362			}
1363		}
1364		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
1365	
1366		// 逐步回放并核验：只把每个事件的金额影响加到运行余额上，不对发生额
1367		// 做累计求和，因此累计补收/收款发生额超过 64 位上限但每步余额合法时
1368		// 仍能成功。
1369		payable := b.TotalFee
1370		var received int64
1371		seen := make(map[int64]string, len(events))
1372		for i := range events {
1373			ev := &events[i]
1374			desc := ev.kind + " " + ev.refID
1375			if prev, dup := seen[ev.seq]; dup {
1376				return nil, fmt.Errorf("流水序号 %d 重复（%s 与 %s），数据异常，拒绝输出流水", ev.seq, prev, desc)
1377			}
1378			seen[ev.seq] = desc
1379			if ev.linkSeq != 0 && ev.linkSeq >= ev.seq {
1380				return nil, fmt.Errorf("%s 的撤销序号 %d 不晚于原操作序号 %d，数据异常，拒绝输出流水", desc, ev.seq, ev.linkSeq)
1381			}
1382			var err error
1383			if payable, err = addSigned64(payable, ev.deltaPayable); err != nil {
1384				return nil, fmt.Errorf("序号 %d（%s）之后应付越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1385			}
1386			if received, err = addSigned64(received, ev.deltaReceived); err != nil {
1387				return nil, fmt.Errorf("序号 %d（%s）之后实收越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1388			}
1389			if payable < 0 {
1390				return nil, fmt.Errorf("序号 %d（%s）之后应付为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, payable)
1391			}
1392			if received < 0 {
1393				return nil, fmt.Errorf("序号 %d（%s）之后实收为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, received)
1394			}
1395			if received > payable {
1396				return nil, fmt.Errorf("序号 %d（%s）之后实收 %d 分超过应付 %d 分，数据异常，拒绝输出流水", ev.seq, desc, received, payable)
1397			}
1398			ev.afterPayable = payable
1399			ev.afterReceived = received
1400		}
1401		return events, nil
1402	}
1403	
1404	func cmdBillLedger(dir, customerID, month, cutoffText string, hasCutoff bool) error {
1405		if !validMonth(month) {
1406			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1407		}
1408		s, err := loadStore(dir)
1409		if err != nil {
1410			return err
1411		}
1412		cust, ok := s.Customers[customerID]
1413		if !ok {
1414			return fmt.Errorf("客户标识 %q 不存在", customerID)
1415		}
1416		b, ok := s.Bills[billKey(customerID, month)]
1417		if !ok {
1418			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
1419		}
1420	
1421		// 截止序号使用调整/收款及其撤销共用的已保存全局序号：省略表示最新，
1422		// 0 只返回初始余额，截止包含该序号；因其他客户或月份操作造成的序号
1423		// 空档合法。负数、非整数或超过存档全局序号上限一律拒绝。
1424		cutoff := s.NextSeq
1425		cutoffDesc := "省略，按最新"
1426		if hasCutoff {
1427			v, perr := strconv.ParseInt(strings.TrimSpace(cutoffText), 10, 64)
1428			if perr != nil {
1429				return fmt.Errorf("截止操作序号 %q 不是非负整数: %w", cutoffText, perr)
1430			}
1431			if v < 0 {
1432				return fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
1433			}
1434			if v > s.NextSeq {
1435				return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", v, s.NextSeq)
1436			}
1437			cutoff = v
1438			cutoffDesc = "指定"
1439		}
1440	
1441		// 先核验目标账单的完整流水：任何异常（即使发生在截止序号之后）都
1442		// 拒绝，不输出部分正常的报告。
1443		events, err := billLedger(s, b)
1444		if err != nil {
1445			return err
1446		}
1447		printBillLedger(b, cust, s.NextSeq, cutoff, cutoffDesc, events)
1448		return nil
1449	}
1450	
1451	func printBillLedger(b *bill, cust *customer, nextSeq, cutoff int64, cutoffDesc string, events []ledgerEvent) {
1452		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
1453		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
1454		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
1455		fmt.Fprintf(stdout, "原总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
1456		fmt.Fprintf(stdout, "存档全局序号上限：%d\n", nextSeq)
1457		fmt.Fprintf(stdout, "截止操作序号：%d（%s）\n", cutoff, cutoffDesc)
1458		fmt.Fprintf(stdout, "初始余额：应付 %d 分（%s），实收 0 分（%s），未收余额 %d 分（%s）\n",
1459			b.TotalFee, moneyFen(b.TotalFee), moneyFen(0), b.TotalFee, moneyFen(b.TotalFee))
1460	
1461		// 截止包含该序号；截止之后的事件（含撤销）既不出现也不影响历史余额。
1462		payable, received := b.TotalFee, int64(0)
1463		var shown []ledgerEvent
1464		for _, ev := range events {
1465			if ev.seq > cutoff {
1466				continue
1467			}
1468			shown = append(shown, ev)
1469			payable, received = ev.afterPayable, ev.afterReceived
1470		}
1471		if len(shown) == 0 {
1472			fmt.Fprintln(stdout, "流水：无（截止序号以内该账单无账后事件）")
1473		} else {
1474			fmt.Fprintln(stdout, "流水（按操作序号升序）：")
1475			for i, ev := range shown {
1476				fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(ev))
1477			}
1478		}
1479		fmt.Fprintf(stdout, "截止时余额：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1480			payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1481	}
1482	
1483	// formatLedgerEvent 渲染一条流水事件：序号、类型、原记录标识、金额影响、
1484	// 原因或备注、撤销关联，以及事件后的应付、实收、未收余额；收款类事件同时
1485	// 说明汇款总额与本账单分配。
1486	func formatLedgerEvent(ev ledgerEvent) string {
1487		after := fmt.Sprintf("事后：应付 %d 分，实收 %d 分，未收余额 %d 分",
1488			ev.afterPayable, ev.afterReceived, ev.afterPayable-ev.afterReceived)
1489		switch ev.kind {
1490		case "调整":
1491			return fmt.Sprintf("序号 %d 调整 %s：应付 %+d 分（%s，%s），原因：%s → %s",
1492				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), adjustKind(ev.deltaPayable), ev.note, after)
1493		case "撤销调整":
1494			return fmt.Sprintf("序号 %d 撤销调整 %s：应付 %+d 分（%s，关联序号 %d 的调整 %s），原因：%s → %s",
1495				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), ev.linkSeq, ev.refID, ev.note, after)
1496		case "收款":
1497			return fmt.Sprintf("序号 %d 收款 %s：实收 %+d 分（%s，汇款总额 %d 分，本账单分配 %d 分），备注：%s → %s",
1498				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payTotal, ev.payAlloc, ev.note, after)
1499		case "更正":
1500			return fmt.Sprintf("序号 %d 更正 %s：实收 %+d 分（%s，关联收款 %s，本账单分配 %d 分 → %d 分），原因：%s → %s",
1501				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.beforeAlloc, ev.afterAlloc, ev.note, after)
1502		default: // 撤销收款
1503			return fmt.Sprintf("序号 %d 撤销收款 %s：实收 %+d 分（%s，关联序号 %d 的收款 %s，汇款总额 %d 分，取消本账单分配 %d 分），原因：%s → %s",
1504				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.linkSeq, ev.refID, ev.payTotal, ev.payAlloc, ev.note, after)
1505		}
1506	}
1507

