```go
func priceTiered(tiers []planTier, cum, qty int64) ([]billLineTier, int64, int64, error) {
    if cum < 0 || qty < 0 { return error }
    var segs []billLineTier
    var fee int64
    remaining := qty
    for i, t := range tiers {
        if remaining == 0 { break }
        var avail int64
        if t.Limit == 0 { // 无上限（最后一档）
            avail = remaining
        } else {
            if cum >= t.Limit { continue }
            avail = t.Limit - cum
            if avail > remaining { avail = remaining }
        }
        take := avail
        segFee, err := mul64(take, t.Price)
        ...
        fee, err = add64(fee, segFee)
        cum, err = add64(cum, take)  // cum+take ≤ limit or cum+qty; qty ≤ MaxInt64-cum? cum+take could overflow if unlimited tier and cum+qty > MaxInt64 → add64 catches
        segs = append(segs, billLineTier{Tier: i, Quantity: take, UnitPrice: t.Price, Fee: segFee})
        remaining -= take
    }
    if remaining > 0 { return error "阶梯未覆盖" } // can't happen if last unlimited
    return segs, cum, fee, nil
}
```

