```go
func parseTiers(args []string) ([]planTier, error) {
    if len(args) == 0 { return nil, fmt.Errorf("至少需要一个阶梯档：...)") }
    tiers := make([]planTier, 0, len(args))
    for i, arg := range args {
        last := i == len(args)-1
        if strings.Contains(arg, ":") {
            if last { return nil, fmt.Errorf("最后一档无上限，只给单价分（如 5），收到 %q", arg) }
            parts := strings.Split(arg, ":")
            if len(parts) != 2 { error }
            limit, err := parsePositiveInt(parts[0], "上限")
            price, err := parsePrice(parts[1])  // reuse non-negative parser
            tiers = append(tiers, planTier{Limit: limit, Price: price})
        } else {
            if !last { return nil, fmt.Errorf("第 %d 档 %q 缺少累计上限，应为 上限:单价分", i+1, arg) }
            price, err := parsePrice(arg)
            tiers = append(tiers, planTier{Limit: 0, Price: price})
        }
    }
    // strictly increasing check
    for i := 1; i < len(tiers)-1; i++ { if tiers[i].Limit <= tiers[i-1].Limit { error } }
    return tiers, nil
}
