func validateTiers(tiers []planTier) error {
    if len(tiers) == 0 { return errors.New("至少一档") }
    for i, t := range tiers {
        if t.Price < 0 { return fmt.Errorf("第 %d 档单价为负", i+1) }
        if i < len(tiers)-1 {
            if t.Limit <= 0 { return fmt.Errorf("第 %d 档上限必须是正整数", i+1) }
            if i > 0 && t.Limit <= tiers[i-1].Limit { return fmt.Errorf("上限必须严格递增") }
        } else if t.Limit != 0 {
            return errors.New("最后一档必须无上限")
        }
    }
    return nil
}
